<?php
/* 3G's readability fix v2 (readfix2) - 2026-11-01.
   v1 put the block after the FIRST </head>. On these hand-built pages that is not the
   structural end of the head - 19 more stylesheets follow it - so the fix was outranked
   on some sites. v2 puts the block LAST in the document, before </body>, where it wins.
   It changes TEXT COLOUR ONLY. No layout, no copy, no buttons, nothing removed.
   Any v1 block is removed first, so running this once replaces it cleanly. */
@ini_set('display_errors','0');
$REPORT = __DIR__ . '/readfix2-report.txt';
$log=[];
function out($s){ global $log,$REPORT; $log[]=$s; @file_put_contents($REPORT, implode("\n",$log)."\n"); echo $s."\n"; }
set_error_handler(function($n,$m,$f,$l){ out("PHP ERROR: $m ($f:$l)"); return true; });
register_shutdown_function(function(){ $e=error_get_last(); if($e && in_array($e['type'],[E_ERROR,E_PARSE,E_COMPILE_ERROR],true)) out('FATAL: '.$e['message']); });
if (($_GET['go'] ?? '') !== '11330217338657c5') { http_response_code(404); exit; }
header('Content-Type: text/plain; charset=utf-8');
$BASE = '/home/u732570899/domains';
$stamp = date('Ymd'); $tag='readfix2';
$P = json_decode(base64_decode(''), true);
if (!is_array($P)) { out(' UNREADABLE - nothing written'); exit; }
$css = $P['css']; $targets = $P['t'];

$plan=[];
foreach ($targets as $rel => $key) {
  $f = $BASE . '/' . $rel;
  if (!is_file($f)) { out("MISSING (skipped): $rel"); continue; }
  $cur = (string)@file_get_contents($f);
  if ($cur === '') { out("UNREADABLE (skipped): $rel"); continue; }
  if (!isset($css[$key])) { out("NO CSS for key $key (skipped): $rel"); continue; }
  /* drop any earlier block so we never stack two */
  $clean = preg_replace('~\n?<style id="ttfix">.*?</style>\n?~is', '', $cur);
  if ($clean === null) { out("REGEX FAILED (skipped): $rel"); continue; }
  $had = ($clean !== $cur) ? ' (replaced v1)' : '';
  $block = "\n<style id=\"ttfix\">/* readability fix " . $stamp . " - text colour only */\n" . $css[$key] . "\n</style>\n";
  $pos = strripos($clean, '</body>');
  $where = 'before </body>';
  if ($pos === false) { $pos = strripos($clean, '</head>'); $where = 'before last </head>'; }
  if ($pos === false) { $pos = strlen($clean); $where = 'appended'; }
  $new = substr($clean,0,$pos) . $block . substr($clean,$pos);
  $plan[] = [$f, $rel, $new, strlen($block), $where, $had];
}
if (!$plan) { out('--- nothing to do ---'); exit; }
$n=0; $baks=0;
foreach ($plan as $p) {
  list($f,$rel,$new,$len,$where,$had) = $p;
  $bk = $f . '.bak-' . $stamp . '-' . $tag;
  if (!is_file($bk)) { if (@copy($f,$bk)) $baks++; else { out("CANNOT BACK UP (skipped): $rel"); continue; } }
  if (@file_put_contents($f,$new) === false) { out("WRITE FAILED: $rel"); continue; }
  out("fixed $rel (+{$len}b, {$where}{$had})"); $n++;
}
out('--- DONE. pages fixed: ' . $n . ', backups made: ' . $baks . ' ---');
